"""Compressed byte-sequence API for the payload extension.

A *node* is an immutable description of a logical byte sequence.  Literal input
becomes :class:`Lit`; concatenation, repetition and slicing keep their operands
instead of expanding them, so a capture part such as ``b"x" * 10**18`` never
materialises.  Length, exact fingerprint and line search are derived from the
structure:

* ``len(A + B) == len(A) + len(B)``
  ``hash(A + B) == hash(A) * 257**len(B) + hash(B)  (mod 2**64)``
* ``hash(X**m) == hash(X) * sum_{i<m} (257**len(X))**i`` -- geometric doubling
* ranges are decomposed into whole subtrees (memoised) plus at most two
  boundary pieces per repetition level.

All traversals are iterative so a deep definition chain cannot exhaust the
interpreter stack.
"""
import array
import ast
import hashlib
import keyword
import re
import sys
from bisect import bisect_left, bisect_right

MAX = (1 << 63) - 1
MASK = (1 << 64) - 1
MOD = 1 << 64
BASE = 257
BASE2 = BASE * BASE

#: merge/run cache thresholds
MERGE_LIMIT = 1 << 16
RAW_LIMIT = 1 << 16

IDENT = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,31}\Z', re.ASCII)
RANDOM_TOKEN = '<<random_string>>'
LF = 10

_pow_cache = {e: pow(BASE, e, MOD) for e in range(512)}
_word_table = None


def p257(exponent):
    """257**exponent modulo 2**64 (cached)."""
    value = _pow_cache.get(exponent)
    if value is None:
        value = pow(BASE, exponent, MOD)
        if len(_pow_cache) < 262144:
            _pow_cache[exponent] = value
    return value


def _table():
    global _word_table
    if _word_table is None:
        table = [0] * 65536
        for word in range(65536):
            table[word] = ((word & 255) + 1) * BASE + ((word >> 8) + 1)
        _word_table = table
    return _word_table


def lit_hash(data, lo=0, hi=None):
    """Exact fingerprint of ``data[lo:hi]``."""
    if hi is None:
        hi = len(data)
    count = hi - lo
    if count <= 0:
        return 0
    if count < 24:
        acc = 0
        for index in range(lo, hi):
            acc = (acc * BASE + data[index] + 1) & MASK
        return acc
    chunk = data[lo:hi]
    odd = count & 1
    if odd:
        count -= 1
    words = array.array('H')
    words.frombytes(chunk[:count])
    if sys.byteorder != 'little':
        words.byteswap()
    table = _table()
    acc = 0
    for word in words:
        acc = (acc * BASE2 + table[word]) & MASK
    if odd:
        acc = (acc * BASE + chunk[-1] + 1) & MASK
    return acc


def geometric(node_hash, node_len, count):
    """Fingerprint of ``count`` copies of a sequence (logarithmic in count)."""
    if count <= 0 or node_hash == 0:
        return 0
    ratio = p257(node_len)
    total = 0
    power = 1
    for bit in bin(count)[2:]:
        total = (total * (1 + power)) & MASK
        power = (power * power) & MASK
        if bit == '1':
            total = (total + power) & MASK
            power = (power * ratio) & MASK
    return (node_hash * total) & MASK


class Node:
    """Base class: ``n`` length, ``h`` fingerprint, ``lf`` first LF, ``raw``."""
    __slots__ = ('n', 'h', 'lf', 'raw')

    def __init__(self, length, digest):
        if length > MAX:
            raise ValueError('sequence length overflow')
        self.n = length
        self.h = digest
        self.lf = -2
        self.raw = None

    def __len__(self):
        return self.n


class Lit(Node):
    __slots__ = ('data',)

    def __init__(self, data):
        Node.__init__(self, len(data), lit_hash(data))
        self.data = data
        if len(data) <= RAW_LIMIT:
            self.raw = data


class Cat(Node):
    __slots__ = ('kids', 'offs')

    def __init__(self, kids):
        offs = [0]
        acc = 0
        total = 0
        for kid in kids:
            acc = (acc * p257(kid.n) + kid.h) & MASK
            total += kid.n
            offs.append(total)
        Node.__init__(self, total, acc)
        self.kids = kids
        self.offs = offs


class Rep(Node):
    __slots__ = ('kid', 'count')

    def __init__(self, kid, count):
        Node.__init__(self, kid.n * count, geometric(kid.h, kid.n, count))
        self.kid = kid
        self.count = count


class Cut(Node):
    """A resolved byte slice ``kid[lo:lo+n]``."""
    __slots__ = ('kid', 'lo')

    def __init__(self, kid, lo, hi):
        Node.__init__(self, hi - lo, rhash(kid, lo, hi))
        self.kid = kid
        self.lo = lo


EMPTY = Lit(b'')


def literal(data):
    if type(data) is not bytes:
        raise ValueError('literal bytes required')
    if not data:
        return EMPTY
    return Lit(data)


def size(node):
    return node.n if node is not None else 0


def concat(*items):
    return cat(items)


def cat(items):
    """Concatenate nodes, flattening and merging adjacent literal runs."""
    kids = []
    buffer = bytearray()
    limit = MERGE_LIMIT
    for item in items:
        if item is None or item.n == 0:
            continue
        kind = type(item)
        if kind is Cat:
            if buffer:
                kids.append(Lit(bytes(buffer)))
                del buffer[:]
            kids.extend(item.kids)
            continue
        if kind is Lit and item.n <= limit and len(buffer) + item.n <= limit:
            buffer += item.data
            continue
        if buffer:
            kids.append(Lit(bytes(buffer)))
            del buffer[:]
        kids.append(item)
    if buffer:
        kids.append(Lit(bytes(buffer)))
    if not kids:
        return EMPTY
    if len(kids) == 1:
        return kids[0]
    return Cat(kids)


def repeat(node, count):
    if type(count) is not int or count < 0 or count > MAX:
        raise ValueError('repetition count')
    if count == 0 or node.n == 0:
        return EMPTY
    if count == 1:
        return node
    if node.n * count > MAX:
        raise ValueError('sequence length overflow')
    return Rep(node, count)


def cut(node, start, end):
    if not 0 <= start <= end <= node.n:
        raise ValueError('slice range')
    if start == 0 and end == node.n:
        return node
    if end == start:
        return EMPTY
    return Cut(node, start, end)


def fingerprint(node):
    if node is None:
        return {'n': 0, 'h': '0' * 16}
    return {'n': node.n, 'h': '%016x' % node.h}


def materialize(node, limit=RAW_LIMIT):
    if node is None:
        return b''
    if node.n > limit:
        raise ValueError('bounded materialization')
    return bytes(read_bytes(node, 0, node.n))


# --------------------------------------------------------------------------
# traversals
# --------------------------------------------------------------------------

def _cat_spans(node, lo, hi):
    """Yield ``(kid, a, b)`` for children overlapping ``[lo, hi)`` left to right."""
    offs = node.offs
    first = bisect_right(offs, lo) - 1
    if first < 0:
        first = 0
    last = bisect_left(offs, hi) - 1
    if last >= len(node.kids):
        last = len(node.kids) - 1
    for index in range(first, last + 1):
        base = offs[index]
        yield node.kids[index], (lo if lo > base else base) - base, \
            (hi if hi < offs[index + 1] else offs[index + 1]) - base


def rhash(node, lo, hi=0):
    """Fingerprint of ``node[lo:hi]`` without materialising it."""
    if lo == 0 and hi == node.n:
        return node.h
    if hi <= lo:
        return 0
    acc = 0
    stack = [(node, lo, hi, 0)]
    while stack:
        item = stack.pop()
        current, a, b, copies = item
        if copies:
            span = current.n * copies
            acc = (acc * p257(span) + geometric(current.h, current.n, copies)) & MASK
            continue
        if a >= b:
            continue
        kind = type(current)
        if kind is Lit:
            acc = (acc * p257(b - a) + lit_hash(current.data, a, b)) & MASK
        elif kind is Cut:
            stack.append((current.kid, a + current.lo, b + current.lo, 0))
        elif kind is Cat:
            for kid, ka, kb in reversed(list(_cat_spans(current, a, b))):
                stack.append((kid, ka, kb, 0))
        elif kind is Rep:
            period = current.kid.n
            if period == 0:
                continue
            first = a // period
            last = (b - 1) // period
            if last > first:
                stack.append((current.kid, 0, b - last * period, 0))
                middle = last - first - 1
                if middle > 0:
                    stack.append((current.kid, 0, 0, middle))
            stop = b if b < (first + 1) * period else (first + 1) * period
            stack.append((current.kid, a - first * period, stop - first * period, 0))
        else:
            raise ValueError('unknown node')
    return acc


def range_fingerprint(node, lo, hi):
    if hi <= lo:
        return {'n': 0, 'h': '0' * 16}
    return {'n': hi - lo, 'h': '%016x' % rhash(node, lo, hi)}


def read_bytes(node, lo, hi):
    """Materialise ``node[lo:hi]`` (callers keep this bounded)."""
    out = bytearray()
    if hi <= lo:
        return out
    stack = [(node, lo, hi, 0)]
    while stack:
        current, a, b, copies = stack.pop()
        if copies:
            out += full_bytes(current) * copies
            continue
        if a >= b:
            continue
        kind = type(current)
        if kind is Lit:
            out += current.data[a:b]
        elif kind is Cut:
            stack.append((current.kid, a + current.lo, b + current.lo, 0))
        elif kind is Cat:
            for kid, ka, kb in reversed(list(_cat_spans(current, a, b))):
                stack.append((kid, ka, kb, 0))
        elif kind is Rep:
            period = current.kid.n
            if period == 0:
                continue
            first = a // period
            last = (b - 1) // period
            if last > first:
                stack.append((current.kid, 0, b - last * period, 0))
                middle = last - first - 1
                if middle > 0:
                    stack.append((current.kid, 0, 0, middle))
            stop = b if b < (first + 1) * period else (first + 1) * period
            stack.append((current.kid, a - first * period, stop - first * period, 0))
        else:
            raise ValueError('unknown node')
    return out


def full_bytes(node):
    if node.raw is not None:
        return node.raw
    if node.n > RAW_LIMIT:
        raise ValueError('bounded materialization')
    data = bytes(read_bytes(node, 0, node.n))
    node.raw = data
    return data


def byte_at(node, index):
    if not 0 <= index < node.n:
        raise IndexError('byte offset')
    chunk = read_bytes(node, index, index + 1)
    return chunk[0]


def find_lf(node, lo, hi):
    """First LF in ``node[lo:hi)`` as a node-relative index, else -1."""
    if hi > node.n:
        hi = node.n
    best = -1
    if hi <= lo:
        return -1
    stack = [(node, lo, hi)]
    while stack:
        current, a, b = stack.pop()
        if a >= b:
            continue
        if best >= 0 and a >= best:
            continue
        kind = type(current)
        if kind is Lit:
            found = current.data.find(LF, a, b)
            if found >= 0:
                best = found
        elif kind is Cut:
            stack.append((current.kid, a + current.lo, b + current.lo))
        elif kind is Cat:
            for kid, ka, kb in reversed(list(_cat_spans(current, a, b))):
                if best >= 0 and current.offs[0] + ka >= best:
                    continue
                stack.append((kid, ka, kb))
        elif kind is Rep:
            period = current.kid.n
            if period == 0:
                continue
            inside = first_lf(current.kid)
            if inside < 0:
                continue
            if inside >= a:
                copy = 0
            else:
                copy = (a - inside + period - 1) // period
            found = inside + copy * period
            if found < b and (best < 0 or found < best):
                best = found
        else:
            raise ValueError('unknown node')
    return best


def next_lf(node, start=0, limit=None):
    """First LF at or after ``start`` inside ``limit`` bytes, else -1."""
    if start >= node.n:
        return -1
    stop = node.n if limit is None else min(node.n, start + limit)
    return find_lf(node, start, stop)


def first_lf(node):
    """Memoised first LF index of the whole node (-1 when absent)."""
    known = node.lf
    if known != -2:
        return known
    stack = [node]
    while stack:
        current = stack[-1]
        known = current.lf
        if known != -2:
            stack.pop()
            continue
        kind = type(current)
        if kind is Lit:
            current.lf = current.data.find(LF)
        elif kind is Rep:
            if current.kid.n == 0:
                current.lf = -1
            elif current.kid.lf != -2:
                current.lf = current.kid.lf
            else:
                stack.append(current.kid)
        elif kind is Cut:
            found = find_lf(current.kid, current.lo, current.lo + current.n)
            current.lf = found - current.lo if found >= 0 else -1
        elif kind is Cat:
            result = -1
            pending = None
            for index, kid in enumerate(current.kids):
                if kid.lf == -2:
                    pending = kid
                    break
                if kid.lf >= 0:
                    result = current.offs[index] + kid.lf
                    break
            if pending is None:
                current.lf = result
            else:
                stack.append(pending)
        else:
            raise ValueError('unknown node')
    return node.lf


# --------------------------------------------------------------------------
# expressions and templates
# --------------------------------------------------------------------------

class ExpressionError(ValueError):
    pass


def ast_depth(body):
    """Maximum AST child-edge depth, root body counted as depth 0."""
    best = 0
    stack = [(body, 0)]
    while stack:
        node, depth = stack.pop()
        if depth > best:
            best = depth
        for child in ast.iter_child_nodes(node):
            stack.append((child, depth + 1))
    return best


class Context:
    """Definition environment plus template compilation for one document."""

    def __init__(self, definitions, seed):
        self.seed = seed
        self.definitions = definitions
        self.env = {}
        for name, source in definitions:
            if not IDENT.fullmatch(name) or keyword.iskeyword(name):
                raise ExpressionError('definition name')
            if name in self.env:
                raise ExpressionError('duplicate definition')
            self.env[name] = self.expression(source)

    # -- expressions ------------------------------------------------------
    def expression(self, source):
        if len(source) > 8192:
            raise ExpressionError('expression source budget')
        try:
            tree = ast.parse(source, mode='eval')
        except (SyntaxError, ValueError, RecursionError, MemoryError):
            raise ExpressionError('expression syntax') from None
        body = tree.body
        if ast_depth(body) > 128:
            raise ExpressionError('expression depth')
        value = self._eval(body)
        if not isinstance(value, Node):
            raise ExpressionError('expression must be bytes')
        return value

    def _eval(self, node):
        kind = type(node)
        if kind is ast.Constant:
            value = node.value
            if type(value) is bytes:
                return literal(value)
            if type(value) is str:
                return literal(value.encode('utf8'))
            if type(value) is int:
                if value < 0 or value > MAX:
                    raise ExpressionError('integer literal range')
                return value
            raise ExpressionError('constant type')
        if kind is ast.Name:
            try:
                return self.env[node.id]
            except KeyError:
                raise ExpressionError('unknown name') from None
        if kind is ast.BinOp:
            op = type(node.op)
            left = self._eval(node.left)
            right = self._eval(node.right)
            if op is ast.Add:
                if not isinstance(left, Node) or not isinstance(right, Node):
                    raise ExpressionError('concat operands')
                return cat((left, right))
            if op is ast.Mult:
                if isinstance(left, Node) and type(right) is int:
                    return repeat(left, right)
                if isinstance(right, Node) and type(left) is int:
                    return repeat(right, left)
                raise ExpressionError('repeat operands')
            raise ExpressionError('operator')
        if kind is ast.Subscript:
            target = self._eval(node.value)
            if not isinstance(target, Node):
                raise ExpressionError('slice operand')
            selector = node.slice
            if type(selector) is not ast.Slice:
                raise ExpressionError('slice form')
            if selector.step is not None:
                raise ExpressionError('slice step')
            lo = 0 if selector.lower is None else self._index(selector.lower)
            hi = target.n if selector.upper is None else self._index(selector.upper)
            if not 0 <= lo <= hi <= target.n:
                raise ExpressionError('slice range')
            return cut(target, lo, hi)
        raise ExpressionError('syntax %s' % kind.__name__)

    def _index(self, node):
        if type(node) is not ast.Constant or type(node.value) is not int:
            raise ExpressionError('slice endpoint')
        value = node.value
        if value < 0 or value > MAX:
            raise ExpressionError('slice endpoint range')
        return value

    # -- templates --------------------------------------------------------
    def template(self, value, coordinate):
        if type(value) is not str:
            raise ExpressionError('template type')
        if value.startswith('{{') and value.endswith('}}'):
            return self.expression(value[2:-2].strip())
        if value.find(RANDOM_TOKEN) < 0:
            return literal(value.encode('utf8'))
        pieces = []
        index = 0
        occurrence = 0
        span = len(RANDOM_TOKEN)
        while True:
            found = value.find(RANDOM_TOKEN, index)
            if found < 0:
                pieces.append(value[index:])
                break
            pieces.append(value[index:found])
            digest = hashlib.sha256(
                ('%s/%s/%d' % (self.seed, coordinate, occurrence)).encode('utf8')
            ).hexdigest()[:20]
            pieces.append(digest)
            index = found + span
            occurrence += 1
        return literal(''.join(pieces).encode('utf8'))
